export default function ForbiddenPage() {
  return (
    <main style={{
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      minHeight: '100vh',
      padding: '2rem',
      textAlign: 'center',
      backgroundColor: '#f8f9fa'
    }}>
      <div style={{
        maxWidth: '600px',
        padding: '3rem',
        backgroundColor: 'white',
        borderRadius: '12px',
        boxShadow: '0 4px 6px rgba(0, 0, 0, 0.1)'
      }}>
        <h1 style={{
          fontSize: '4rem',
          margin: '0 0 1rem 0',
          color: '#dc3545'
        }}>
          403
        </h1>
        <h2 style={{
          fontSize: '1.5rem',
          margin: '0 0 1rem 0',
          color: '#343a40'
        }}>
          Access Forbidden
        </h2>
        <p style={{
          fontSize: '1rem',
          color: '#6c757d',
          marginBottom: '2rem'
        }}>
          You don't have permission to access this page. This area is restricted to administrators only.
        </p>
        <a
          href="/"
          style={{
            display: 'inline-block',
            padding: '0.75rem 1.5rem',
            backgroundColor: '#007bff',
            color: 'white',
            textDecoration: 'none',
            borderRadius: '6px',
            fontSize: '1rem',
            fontWeight: '500'
          }}
        >
          Go Back Home
        </a>
      </div>
    </main>
  );
}

